import React, { useEffect, useMemo, useState } from 'react';
import api from '../../services/api';

interface GradeRecord {
  gradeId: number | string;
  term: string;
  gradeValue: string;
  gradePoint: number;
  midtermGrade: number;
  finalGrade: number;
  overallScore: number;
  course: {
    courseId: number | string;
    courseCode: string;
    courseName: string;
    credits: number;
  };
}

const DEFAULT_GRADES: GradeRecord[] = [
  // HKI 2025-2026
  {
    gradeId: 1,
    term: 'HKI 2025-2026',
    gradeValue: '8.70',
    gradePoint: 4.0,
    midtermGrade: 8.5,
    finalGrade: 8.8,
    overallScore: 8.7,
    course: {
      courseId: 1,
      courseCode: 'BAA00005',
      courseName: 'General Economics',
      credits: 2,
    },
  },
  {
    gradeId: 2,
    term: 'HKI 2025-2026',
    gradeValue: '9.10',
    gradePoint: 4.0,
    midtermGrade: 9.0,
    finalGrade: 9.2,
    overallScore: 9.1,
    course: {
      courseId: 2,
      courseCode: 'BAA00030',
      courseName: 'National Defense Education',
      credits: 4,
    },
  },
  {
    gradeId: 3,
    term: 'HKI 2025-2026',
    gradeValue: '8.40',
    gradePoint: 3.5,
    midtermGrade: 8.0,
    finalGrade: 8.7,
    overallScore: 8.4,
    course: {
      courseId: 3,
      courseCode: 'CSC10009',
      courseName: 'Computer Systems',
      credits: 2,
    },
  },
  {
    gradeId: 4,
    term: 'HKI 2025-2026',
    gradeValue: '9.30',
    gradePoint: 4.0,
    midtermGrade: 9.5,
    finalGrade: 9.2,
    overallScore: 9.3,
    course: {
      courseId: 4,
      courseCode: 'CSC10014',
      courseName: 'Computational Thinking',
      credits: 4,
    },
  },
  {
    gradeId: 5,
    term: 'HKI 2025-2026',
    gradeValue: '8.50',
    gradePoint: 4.0,
    midtermGrade: 8.5,
    finalGrade: 8.5,
    overallScore: 8.5,
    course: {
      courseId: 5,
      courseCode: 'MTH00006',
      courseName: 'Calculus 2',
      credits: 4,
    },
  },

  // HKII 2025-2026
  {
    gradeId: 6,
    term: 'HKII 2025-2026',
    gradeValue: '9.00',
    gradePoint: 4.0,
    midtermGrade: 9.0,
    finalGrade: 9.0,
    overallScore: 9.0,
    course: {
      courseId: 6,
      courseCode: 'BAA00021',
      courseName: 'Physical Education 1',
      credits: 2,
    },
  },
  {
    gradeId: 7,
    term: 'HKII 2025-2026',
    gradeValue: '8.30',
    gradePoint: 3.5,
    midtermGrade: 8.0,
    finalGrade: 8.5,
    overallScore: 8.3,
    course: {
      courseId: 7,
      courseCode: 'BAA00101',
      courseName: 'Marxist-Leninist Philosophy',
      credits: 3,
    },
  },
  {
    gradeId: 8,
    term: 'HKII 2025-2026',
    gradeValue: '8.80',
    gradePoint: 4.0,
    midtermGrade: 8.5,
    finalGrade: 9.0,
    overallScore: 8.8,
